{"cards": [{"node_code": "N_194ecffa0a7afcd0", "definition": "汽车运行中除燃料和常规润滑油外，用于维持系统功能、密封、冷却或特殊性能的专用化学材料，包括防冻液、制动液、密封胶及特定添加剂。", "boundary": "本节点收录汽车运行所需的非燃料类辅助材料。边界在于区分“燃料”（提供能量，归入液体/气体燃料节点）、“常规润滑油”（主要起润滑作用，归入润滑油节点）。若材料主要功能是润滑，归入润滑油节点；若主要功能是冷却、制动、密封或作为燃料添加剂，归入本节点。", "includes": ["防冻液、制动液、减震液等液压与冷却介质", "密封胶、堵漏剂等车身及管路密封材料", "抗爆剂、变速器油等特定功能添加剂或专用油液"], "excludes": ["汽油、柴油等车用燃料（归入液体燃料节点）", "发动机机油、齿轮油等以润滑为主要功能的油品（归入润滑油节点）"], "sibling_distinctions": [{"other_code": "N_893747ce35819fcc", "rule": "区分依据为功能：润滑油节点侧重摩擦副间的润滑与减磨；本节点侧重冷却、制动、密封或作为燃料添加剂等非润滑功能材料。"}, {"other_code": "N_2ce1302c95b236f8", "rule": "区分依据为对象：燃料添加剂节点专门针对改善燃料燃烧性能的添加剂；本节点收录其他行车辅助材料，若抗爆剂被单独列出则归本节点，否则视具体分类习惯，通常抗爆剂属燃料添加剂，但此处树结构将其置于本节点下，故以树结构为准，收录抗爆剂。"}], "cross_boundary_rule": "若材料兼具润滑与冷却功能（如某些液压油），侧重润滑归润滑油节点，侧重液压传动或冷却归本节点。"}, {"node_code": "N_3b39717300c233d4", "definition": "汽车燃料及润滑料的储存、加注、配送设施及其配套设备，包括加油站、加气站、充电站的建筑布局、工艺流程及专用设备。", "boundary": "本节点聚焦于“供给设施”与“设备”。边界在于区分“燃料本身”（归入燃料节点）、“车辆加注系统”（归入汽车工程）。若内容涉及加油站的安全管理、环保设施或自动化控制，归入本节点。不包含燃料的生产制造过程。", "includes": ["加油站、加气站、充电站的选址、设计与建设", "加油机、加气机、充电桩等加注设备的技术与维护", "燃料储存罐区、管道输送系统及站内安全环保设施"], "excludes": ["汽油、柴油等燃料的化学性质与生产（归入燃料节点）", "汽车油箱、燃油泵等车载加注系统（归入汽车工程）"], "sibling_distinctions": [{"other_code": "N_c9db81363d7f71c4", "rule": "区分依据为对象：液体燃料节点关注燃料本身的性质与选用；本节点关注燃料的储存与加注设施及设备。"}], "cross_boundary_rule": "若内容涉及“电动汽车充电网络规划”，侧重电网接入与电力设施归入电力类（若树中有），侧重充电站站级设施归入本节点。"}, {"node_code": "N_d17da70f4974721a", "definition": "汽车运行过程中产生的废气、噪声等对大气环境的影响，以及相应的污染物检测、控制技术与排放标准。", "boundary": "本节点聚焦于“汽车尾气”与“环保”。边界在于区分“发动机排放控制”（侧重发动机内部燃烧优化，归入汽车工程）、“通用大气污染”（非汽车源，归入环境科学）。若内容涉及三元催化器、颗粒捕集器等后处理装置，归入本节点。", "includes": ["汽车尾气成分分析、排放测试方法与标准", "三元催化转化器、颗粒捕集器等尾气后处理技术", "汽车噪声控制及对环境的影响评估"], "excludes": ["发动机燃烧室设计、喷油策略等源头减排技术（归入汽车工程）", "非汽车源的大气污染控制（归入环境科学）"], "sibling_distinctions": [{"other_code": "N_194ecffa0a7afcd0", "rule": "区分依据为功能：其他行车材料节点关注材料本身；本节点关注材料或技术对环境污染的控制与消除。"}], "cross_boundary_rule": "若内容涉及“新能源汽车零排放”，侧重电池与电机归入汽车工程，侧重全生命周期环境影响评估归入本节点。"}]}
